import React, { useState } from 'react';
import { FileUploader } from "react-drag-drop-files";
import { DIVISA, crearNuevoProducto } from '../tienda/tienda.js';

const FormularioNuevosProductos = ({ onAgregarProducto, deshabilitado }) => {
    const fileTypes = ["JPG", "PNG", "GIF", "JPEG"];

    // Estados
    const [formData, setFormData] = useState({
        tipo: '',
        nombre: '',
        precio: '',
        descripcion: '',
        extra: ''
    });
    const [file, setFile] = useState(null);

    // Alertas (Sistema centralizado y animado)
    const [alerta, setAlerta] = useState({ visible: false, texto: "", tipo: "" });
    const mostrarAlerta = (texto, tipo = "danger") => {
        setAlerta({ visible: true, texto, tipo });
        setTimeout(() => setAlerta({ visible: false, texto: "", tipo: "" }), 3000);
    };

    // HandleChange unificado
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    // Mapas dinámicos (Tus campos originales)
    const placeholdersExtra = {
        Mobiliario: "ej: Madera",
        Alimentacion: "ej: Sabor Pollo",
        Cabello: "ej: Rizado",
        Juguete: "ej: Peluche",
        Merchandising: "ej: Cabeza",
        Accesorios: "ej: Perro"
    };

    const titulosExtra = {
        Mobiliario: "Material",
        Alimentacion: "Tipo de Alimento",
        Cabello: "Estilo",
        Juguete: "Tipo de Juguete",
        Merchandising: "Parte del cuerpo",
        Accesorios: "Tipo de Mascota"
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (deshabilitado) return;

        // Validaciones mejoradas
        if (!formData.tipo) return mostrarAlerta("Debes escoger un tipo de producto");
        
        const precioNum = parseFloat(formData.precio);
        if (isNaN(precioNum) || precioNum <= 0) return mostrarAlerta("Introduce un precio válido");

        const nuevoProducto = {
            id: "prod-" + Date.now(),
            nombre: formData.nombre,
            precio: precioNum,
            descripcion: formData.descripcion,
            tipo: formData.tipo,
            // Mantenemos tu lógica de imagen original
            imagen: file ? URL.createObjectURL(file) : 'imagenes/productos/default.png',
            extra: formData.extra
        };

        try {
            const productoInstanciado = crearNuevoProducto(formData.tipo.toLowerCase(), nuevoProducto);
            if (productoInstanciado) {
                onAgregarProducto(formData.tipo, productoInstanciado);
                mostrarAlerta("¡Producto añadido con éxito!", "success");
                
                // Limpieza total del formulario
                setFormData({ tipo: '', nombre: '', precio: '', descripcion: '', extra: '' });
                setFile(null);
            } else {
                mostrarAlerta("Error: El producto ya existe o no se pudo crear");
            }
        } catch (error) {
            console.error(error);
            mostrarAlerta("Error crítico al añadir el producto");
        }
    };

    return (
        <div className="formulario-wrapper card p-4 shadow border-0" style={{ borderRadius: '15px' }}>
            <h3 className="text-center mb-4 text-primary fw-bold">Añadir Nuevo Producto</h3>
            <form id="form-producto" onSubmit={handleSubmit}>
                
                {/* Tipo de producto */}
                <div className="mb-3">
                    <label className="form-label fw-bold text-muted">Categoría</label>
                    <select
                        name="tipo"
                        className="form-select form-select-lg shadow-sm"
                        value={formData.tipo}
                        onChange={(e) => { handleChange(e); setFormData(prev => ({ ...prev, extra: '' })); }}
                        required
                        disabled={deshabilitado}
                        style={{ borderLeft: '5px solid var(--bs-primary)' }}
                    >
                        <option value="">Selecciona una categoría...</option>
                        {Object.keys(placeholdersExtra).map(t => (
                            <option key={t} value={t}>{t}</option>
                        ))}
                    </select>
                </div>

                {/* Nombre y Precio en una fila */}
                <div className="row">
                    <div className="col-md-8 mb-3">
                        <label className="form-label fw-bold text-muted">Nombre</label>
                        <input type="text" name="nombre" className="form-control form-control-lg shadow-sm" value={formData.nombre} onChange={handleChange} placeholder="Ej: Pelota de goma" required disabled={deshabilitado} />
                    </div>
                    <div className="col-md-4 mb-3">
                        <label className="form-label fw-bold text-muted">Precio ({DIVISA})</label>
                        <input type="number" name="precio" className="form-control form-control-lg shadow-sm" value={formData.precio} onChange={handleChange} step="0.01" min="0" placeholder="0.00" required disabled={deshabilitado} />
                    </div>
                </div>

                {/* Campo Extra Dinámico (con estilo destacado) */}
                {formData.tipo && placeholdersExtra[formData.tipo] && (
                    <div className="mb-3 animate__animated animate__fadeInUp">
                        <label className="form-label fw-bold text-primary">{titulosExtra[formData.tipo]}</label>
                        <input type="text" name="extra" className="form-control form-control-lg border-primary shadow-sm" value={formData.extra} onChange={handleChange} placeholder={placeholdersExtra[formData.tipo]} required disabled={deshabilitado} />
                    </div>
                )}

                {/* Descripción */}
                <div className="mb-3">
                    <label className="form-label fw-bold text-muted">Descripción Corta</label>
                    <textarea name="descripcion" className="form-control shadow-sm" value={formData.descripcion} onChange={handleChange} placeholder="Describe brevemente el producto..." rows="2" disabled={deshabilitado}></textarea>
                </div>

                {/* Sección de Imagen (Tu lógica original con estilos mejorados) */}
                <div className="mb-4">
                    <label className="form-label fw-bold text-muted">Imagen del Producto</label>
                    
                    {/* Input de archivo tradicional */}
                    <input
                        type="file"
                        className="form-control shadow-sm mb-3"
                        accept="image/*"
                        disabled={deshabilitado}
                        onChange={(e) => e.target.files && setFile(e.target.files[0])}
                    />
                    
                    {/* Zona de Drag & Drop (Mantenemos tu children y estilos base) */}
                    <div className={`drop-zone-custom p-3 border rounded ${deshabilitado ? 'bg-light' : ''}`} 
                         style={{
                            cursor: deshabilitado ? 'not-allowed' : 'pointer',
                            borderStyle: 'dashed',
                            borderColor: deshabilitado ? '#ced4da' : '#0d6efd',
                            backgroundColor: deshabilitado ? '#e9ecef' : '#f8f9fa'
                         }}>
                        <FileUploader
                            handleChange={(file) => setFile(file)}
                            name="file"
                            types={fileTypes}
                            disabled={deshabilitado}
                            hoverTitle="Suelta aquí"
                            classes="w-100"
                        >
                            {/* Tu Children Original (con pequeños ajustes de espaciado) */}
                            {file ? (
                                <div className="animate__animated animate__fadeIn text-center">
                                    <img
                                        src={URL.createObjectURL(file)}
                                        alt="Vista previa"
                                        style={{ maxWidth: '80px', borderRadius: '5px', opacity: deshabilitado ? 0.5 : 1 }}
                                        className="mb-2 d-block mx-auto shadow-sm"
                                    />
                                    <p className="text-success m-0 small fw-bold">{deshabilitado ? "MODO OFFLINE" : `✓ ${file.name}`}</p>
                                </div>
                            ) : (
                                <div className="text-center py-2">
                                    <i className={`bi bi-cloud-arrow-up fs-2 ${deshabilitado ? 'text-muted' : 'text-primary'}`}></i>
                                    <p className="m-0 small text-muted">
                                        {deshabilitado ? "Formulario deshabilitado" : "O arrastra tu imagen aquí"}
                                    </p>
                                </div>
                            )}
                        </FileUploader>
                    </div>
                </div>

                <button type="submit" className={`btn ${deshabilitado ? 'btn-secondary' : 'btn-primary'} btn-lg w-100 py-3 fw-bold shadow`} disabled={deshabilitado}>
                    {deshabilitado ? "MODO OFF-LINE (Sin Conexión)" : "GUARDAR Y SUBIR PRODUCTO"}
                </button>

                {/* Sistema de Alertas (Animado para errores y éxito) */}
                {alerta.visible && (
                    <div className={`alert alert-${alerta.tipo} mt-3 animate__animated animate__shakeX text-center fw-bold shadow-sm`}>
                        <i className={`bi ${alerta.tipo === 'success' ? 'bi-check-circle-fill' : 'bi-exclamation-triangle-fill'} me-2`}></i>
                        {alerta.texto}
                    </div>
                )}
            </form>
        </div>
    );
};

export default FormularioNuevosProductos;
